namespace sv_f171ae952d4e47a29958bac0d24d6633.Client.Services;

public interface IShipmentService
{
    Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

public record ShipmentDetails(
    string TrackingNumber,
    string Status,
    string Location,
    DateTimeOffset EstimatedDelivery,
    IReadOnlyList<StatusUpdate> Updates);

public record StatusUpdate(string Description, DateTimeOffset Timestamp);

namespace sv_f171ae952d4e47a29958bac0d24d6633.Client.Services;

public class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, ShipmentDetails> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["PKG-001"] = new ShipmentDetails(
            "PKG-001",
            "In Transit",
            "Chicago, IL",
            new DateTimeOffset(2026, 6, 14, 17, 0, 0, TimeSpan.Zero),
            [
                new StatusUpdate("Package picked up", new DateTimeOffset(2026, 6, 8, 9, 0, 0, TimeSpan.Zero)),
                new StatusUpdate("Departed origin facility", new DateTimeOffset(2026, 6, 8, 14, 30, 0, TimeSpan.Zero)),
                new StatusUpdate("Arrived at Chicago hub", new DateTimeOffset(2026, 6, 9, 22, 15, 0, TimeSpan.Zero)),
                new StatusUpdate("In transit to destination", new DateTimeOffset(2026, 6, 10, 6, 0, 0, TimeSpan.Zero)),
            ]),
        ["PKG-002"] = new ShipmentDetails(
            "PKG-002",
            "Delivered",
            "Austin, TX",
            new DateTimeOffset(2026, 6, 9, 12, 0, 0, TimeSpan.Zero),
            [
                new StatusUpdate("Package picked up", new DateTimeOffset(2026, 6, 6, 10, 0, 0, TimeSpan.Zero)),
                new StatusUpdate("In transit", new DateTimeOffset(2026, 6, 7, 8, 0, 0, TimeSpan.Zero)),
                new StatusUpdate("Out for delivery", new DateTimeOffset(2026, 6, 9, 7, 30, 0, TimeSpan.Zero)),
                new StatusUpdate("Delivered – signed by J. Smith", new DateTimeOffset(2026, 6, 9, 11, 45, 0, TimeSpan.Zero)),
            ]),
        ["PKG-003"] = new ShipmentDetails(
            "PKG-003",
            "Processing",
            "Seattle, WA",
            new DateTimeOffset(2026, 6, 18, 20, 0, 0, TimeSpan.Zero),
            [
                new StatusUpdate("Label created", new DateTimeOffset(2026, 6, 10, 0, 30, 0, TimeSpan.Zero)),
            ]),
    };

    public async Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);

        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_f171ae952d4e47a29958bac0d24d6633.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger
@implements IAsyncDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

@if (_loading)
{
    <div class="loading-placeholder">
        <p>Loading shipment details for <strong>@TrackingNumber</strong>…</p>
    </div>
}
else if (_errorMessage is not null)
{
    <div class="error-panel">
        <p>@_errorMessage</p>
        <button @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_shipment is null)
{
    <div class="not-found">
        <p>No shipment found for tracking number <strong>@TrackingNumber</strong>.</p>
    </div>
}
else
{
    <div class="shipment-details">
        <h2>Shipment @_shipment.TrackingNumber</h2>
        <dl>
            <dt>Status</dt>
            <dd>@_shipment.Status</dd>
            <dt>Location</dt>
            <dd>@_shipment.Location</dd>
            <dt>Estimated Delivery</dt>
            <dd>@_shipment.EstimatedDelivery.ToString("f")</dd>
        </dl>

        <h3>Status Updates</h3>
        <ul class="status-updates">
            @foreach (var update in _shipment.Updates)
            {
                <li>
                    <time datetime="@update.Timestamp.ToString("o")">@update.Timestamp.ToString("g")</time>
                    &mdash; @update.Description
                </li>
            }
        </ul>
    </div>
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = default!;

    private ShipmentDetails? _shipment;
    private bool _loading;
    private string? _errorMessage;

    private CancellationTokenSource _cts = new();

    public override async Task SetParametersAsync(ParameterView parameters)
    {
        var previousTrackingNumber = TrackingNumber;
        await base.SetParametersAsync(parameters);

        if (!string.Equals(previousTrackingNumber, TrackingNumber, StringComparison.OrdinalIgnoreCase))
        {
            await CancelPendingRequestAsync();
            await LoadShipmentAsync();
        }
    }

    protected override async Task OnInitializedAsync()
    {
        await LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        _loading = true;
        _errorMessage = null;
        _shipment = null;

        var ct = _cts.Token;

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // Request was intentionally cancelled; do nothing.
            return;
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "Something went wrong loading shipment details. Please try again.";
        }
        finally
        {
            if (!ct.IsCancellationRequested)
            {
                _loading = false;
            }
        }
    }

    private async Task RetryAsync()
    {
        await CancelPendingRequestAsync();
        await LoadShipmentAsync();
    }

    private async Task CancelPendingRequestAsync()
    {
        await _cts.CancelAsync();
        _cts.Dispose();
        _cts = new CancellationTokenSource();
    }

    public async ValueTask DisposeAsync()
    {
        await _cts.CancelAsync();
        _cts.Dispose();
    }
}

